def transform(grid):
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    candidates = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    sep = min(candidates, key=lambda i: counts[grid[i][0]])
    top, bottom = grid[:sep], grid[sep+1:]
    vals = [v for row in top + bottom for v in row]
    bg = max(set(vals), key=vals.count)
    return [[3 if a == bg and b == bg else 2 for a, b in zip(x, y)] for x, y in zip(top, bottom)]
